import{_ as m,C as c,o,c as u,j as n,a,b as l,w as t,E as r,a8 as d,a9 as s}from"./chunks/framework.BOiBTRPC.js";const v=JSON.parse('{"title":"Storage Architectures","description":"Data warehouse vs data lake vs lakehouse vs data mesh — what each buys, where each fails, and how to choose.","frontmatter":{"title":"Storage Architectures","description":"Data warehouse vs data lake vs lakehouse vs data mesh — what each buys, where each fails, and how to choose."},"headers":[],"relativePath":"fundamentals/storage-architectures.md","filePath":"fundamentals/storage-architectures.md"}'),g={name:"fundamentals/storage-architectures.md"};function p(f,e,b,y,w,k){const i=c("Mermaid"),h=c("QuizCard");return o(),u("div",null,[e[8]||(e[8]=n("h1",{id:"storage-architectures",tabindex:"-1"},[a("Storage Architectures "),n("a",{class:"header-anchor",href:"#storage-architectures","aria-label":'Permalink to "Storage Architectures"'},"​")],-1)),e[9]||(e[9]=n("blockquote",null,[n("p",null,[n("strong",null,"Why it matters"),a(" — Every data platform you'll ever touch is one of four architectures (or a hybrid trying to be two). Choosing wrong is the most expensive mistake in the field: you migrate petabytes, rewrite every model, and retrain every consumer. Senior interviews test whether you can defend the trade-offs, not recite vendor marketing.")])],-1)),e[10]||(e[10]=n("h2",{id:"how-we-got-here",tabindex:"-1"},[a("How we got here "),n("a",{class:"header-anchor",href:"#how-we-got-here","aria-label":'Permalink to "How we got here"'},"​")],-1)),e[11]||(e[11]=n("p",null,"Each architecture exists because the previous one couldn't handle a workload. The sequence matters more than the definitions:",-1)),(o(),l(d,null,{default:t(()=>[r(i,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%221980s%3Cbr%2F%3EOLTP%20databases%22%5D%20--%3E%20B%5B%221990s%3Cbr%2F%3EData%20Warehouse%3Cbr%2F%3Eschema-on-write%22%5D%3B%0A%20%20B%20--%3E%20C%5B%222010s%3Cbr%2F%3EData%20Lake%3Cbr%2F%3Eschema-on-read%22%5D%3B%0A%20%20C%20--%3E%20D%5B%22~2020%3Cbr%2F%3ELakehouse%3Cbr%2F%3EACID%20on%20object%20store%22%5D%3B%0A%20%20D%20--%3E%20E%5B%22Org-scale%3Cbr%2F%3EData%20Mesh%3Cbr%2F%3Efederated%20ownership%22%5D%3B%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=s('<table tabindex="0"><thead><tr><th>Architecture</th><th>Triggered by</th><th>It fixed</th></tr></thead><tbody><tr><td>Data warehouse</td><td>BI/OLAP couldn&#39;t run on OLTP boxes</td><td>Analytical queries at reasonable speed</td></tr><tr><td>Data lake</td><td>Warehouses too rigid/expensive for big data + ML</td><td>Cheap storage of everything, any schema</td></tr><tr><td>Lakehouse</td><td>Lakes had no ACID, no schema enforcement, became swamps</td><td>Warehouse features on cheap lake storage</td></tr><tr><td>Data mesh</td><td>Central team became the bottleneck at org scale</td><td>Domain ownership, data-as-product</td></tr></tbody></table><p>The pattern: <strong>centralize → decentralize → reconcile</strong>. Every stage adds a layer without deleting the previous one — most real companies have a lake <em>and</em> a warehouse right now.</p><h2 id="data-warehouse" tabindex="-1">Data warehouse <a class="header-anchor" href="#data-warehouse" aria-label="Permalink to &quot;Data warehouse&quot;">​</a></h2><p>Curated, structured, schema-on-write storage optimized for SQL analytics. Historically shared-nothing MPP engines (Teradata, Netezza, Exadata); today dominated by decoupled storage/compute systems.</p><p><strong>Modern examples:</strong> Snowflake, BigQuery, Redshift, Databricks SQL warehouses, ClickHouse.</p>',5)),(o(),l(d,null,{default:t(()=>[r(i,{id:"mermaid-88",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20WH%5B%22Classic%20warehouse%20architecture%22%5D%0A%20%20%20%20C%5B%22Clients%20%2F%20BI%22%5D%20--%3E%20P%5B%22Query%20planner%22%5D%3B%0A%20%20%20%20P%20--%3E%20E1%5B%22Compute%20node%201%22%5D%3B%0A%20%20%20%20P%20--%3E%20E2%5B%22Compute%20node%202%22%5D%3B%0A%20%20%20%20P%20--%3E%20E3%5B%22Compute%20node%20N%22%5D%3B%0A%20%20%20%20E1%20---%20S%5B%22Shared%20storage%20layer%3Cbr%2F%3Eproprietary%20format%2C%20immutable%22%5D%0A%20%20%20%20E2%20---%20S%3B%0A%20%20%20%20E3%20---%20S%3B%0A%20%20end%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=s('<div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Modern warehouses are <em>all</em> variations of the same idea: immutable storage + elastic compute + automatic optimization. Snowflake stores data in proprietary micro-partitions; BigQuery in Capacitor; Redshift RA3 in managed S3. You cannot read the files directly — that is the price of the managed experience.</p></div><h2 id="data-lake" tabindex="-1">Data lake <a class="header-anchor" href="#data-lake" aria-label="Permalink to &quot;Data lake&quot;">​</a></h2><p>Cheap object storage (S3, GCS, ADLS, HDFS historically) holding files in open formats. Schema is applied at read time, not write time.</p><p><strong>Examples:</strong> S3 + Parquet queried by Spark, Trino, Athena; Hadoop clusters (legacy).</p><table tabindex="0"><thead><tr><th>What it wins</th><th>What it loses</th></tr></thead><tbody><tr><td>Store anything, schema-on-read</td><td>No ACID — partial writes visible</td></tr><tr><td>~$23/TB/month object storage vs $$$ warehouse</td><td>No enforcement → <strong>data swamp</strong></td></tr><tr><td>Any engine can read the files</td><td>Data discoverability collapses without a catalog</td></tr><tr><td>ML/DS workloads read raw data directly</td><td>BI teams can&#39;t find or trust anything</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ The swamp failure mode</p><p>The lake doesn&#39;t fail at ingest — it fails 18 months later when nobody knows which of the 40 <code>customers_*</code> folders is real, the &quot;raw&quot; bucket has PII nobody catalogued, and every team re-derives the same transformations. Ingest without a catalog, lifecycle policy, and ownership is deferred cost, not savings.</p></div><h2 id="data-lakehouse" tabindex="-1">Data lakehouse <a class="header-anchor" href="#data-lakehouse" aria-label="Permalink to &quot;Data lakehouse&quot;">​</a></h2><p>The lakehouse bolts warehouse capabilities onto the lake: an <strong>open table format</strong> (Delta, Iceberg, Hudi — see <a href="/Data-Knowledge/fundamentals/file-formats.html">File &amp; Table Formats</a>) adds ACID transactions, schema enforcement, time travel, and partition management on top of files in object storage.</p>',8)),(o(),l(d,null,{default:t(()=>[r(i,{id:"mermaid-160",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20LH%5B%22Lakehouse%22%5D%0A%20%20%20%20Q%5B%22SQL%20engines%3A%20Spark%20%2F%20Trino%20%2F%20Flink%20%2F%20warehouse%20runtimes%22%5D%20--%3E%20T%5B%22Table%20layer%3Cbr%2F%3EIceberg%20%C2%B7%20Delta%20%C2%B7%20Hudi%3Cbr%2F%3EACID%20%C2%B7%20time%20travel%20%C2%B7%20schema%20evolution%22%5D%3B%0A%20%20%20%20T%20--%3E%20C%5B%22Catalog%3A%20Glue%20%2F%20Hive%20%2F%20REST%20%2F%20Nessie%22%5D%3B%0A%20%20%20%20T%20--%3E%20F%5B%22Object%20storage%3A%20Parquet%2FORC%20files%22%5D%3B%0A%20%20%20%20O%5B%22Streaming%20ingest%20%2B%20ML%20readers%22%5D%20--%3E%20T%3B%0A%20%20end%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[a(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=s('<p>The key insight: <strong>the &quot;warehouse&quot; is now a metadata layer</strong>, not a storage engine. Any engine that understands the table format can read/write the same tables — that is the anti-lock-in property warehouses lack.</p><details class="details custom-block"><summary>Deep dive: why &quot;open format&quot; is the whole point</summary><p>A Snowflake table is only readable by Snowflake. An Iceberg table on S3 is readable by Snowflake, Databricks, Trino, Flink, and duckdb — simultaneously, through a shared catalog. This changes procurement math: you can switch query engines without a migration. The trade is that <em>you</em> now own compaction, clustering, and metadata hygiene that a warehouse does for you.</p></details><h2 id="data-mesh" tabindex="-1">Data mesh <a class="header-anchor" href="#data-mesh" aria-label="Permalink to &quot;Data mesh&quot;">​</a></h2><p>Not a storage technology — an <strong>operating model</strong>. Zhamak Dehghani&#39;s four principles:</p><ol><li><strong>Domain ownership</strong> — teams that produce data own it, not a central DE team.</li><li><strong>Data as a product</strong> — domains ship discoverable, documented, quality-guaranteed datasets.</li><li><strong>Self-serve platform</strong> — a platform team provides tooling so domains don&#39;t rebuild infra.</li><li><strong>Federated computational governance</strong> — global policies enforced via platform, local decisions by domains.</li></ol>',5)),(o(),l(d,null,{default:t(()=>[r(i,{id:"mermaid-197",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20CM%5B%22Central%20model%22%5D%0A%20%20%20%20D1%5B%22Domain%20A%22%5D%20%26%20D2%5B%22Domain%20B%22%5D%20%26%20D3%5B%22Domain%20C%22%5D%20--%3E%20CT%5B%22Central%20data%20team%3Cbr%2F%3Ethe%20bottleneck%22%5D%0A%20%20end%0A%20%20subgraph%20MM%5B%22Mesh%20model%22%5D%0A%20%20%20%20A2%5B%22Domain%20A%3Cbr%2F%3Eowns%20pipelines%22%5D%20--%3E%20P%5B%22Self-serve%20platform%20%2B%20federated%20governance%22%5D%3B%0A%20%20%20%20B2%5B%22Domain%20B%3Cbr%2F%3Eowns%20pipelines%22%5D%20--%3E%20P%3B%0A%20%20%20%20C2%5B%22Domain%20C%3Cbr%2F%3Eowns%20pipelines%22%5D%20--%3E%20P%3B%0A%20%20%20%20P%20--%3E%20X%5B%22Discoverable%20data%20products%22%5D%3B%0A%20%20end%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[a(" Loading... ",-1)])]),_:1})),e[15]||(e[15]=s('<div class="warning custom-block"><p class="custom-block-title">⚠️ Mesh fails organizationally, not technically</p><p>Most failed &quot;mesh&quot; adoptions were tech purchases for an org problem. If a company can&#39;t make domain teams own their <em>services&#39;</em> quality, it won&#39;t make them own data products. Mesh amplifies governance problems — it never fixes them. Precondition: engineering maturity high enough that teams already own their operational quality.</p></div><h2 id="serra-s-taxonomy-mdw-vs-lakehouse-vs-fabric-vs-mesh" tabindex="-1">Serra&#39;s taxonomy: MDW vs lakehouse vs fabric vs mesh <a class="header-anchor" href="#serra-s-taxonomy-mdw-vs-lakehouse-vs-fabric-vs-mesh" aria-label="Permalink to &quot;Serra&#39;s taxonomy: MDW vs lakehouse vs fabric vs mesh&quot;">​</a></h2><p>James Serra (<em>Deciphering Data Architectures</em>, O&#39;Reilly 2024) draws the boundaries differently than marketing does — and his definitions are the ones that survive scrutiny:</p><ul><li><strong>Modern Data Warehouse (MDW)</strong> — a <em>two-tier</em> pattern: data lake for landing/transform/ML <strong>plus</strong> a relational warehouse that holds a <em>copy</em> of curated data for BI. Serra&#39;s litmus test: &quot;if no data is replicated from the lake into an RDW, it&#39;s a lakehouse, not an MDW.&quot;</li><li><strong>Lakehouse</strong> — <em>one-tier</em>: the lake does both jobs; the warehouse is deleted, not layered.</li><li><strong>Data fabric</strong> — an MDW plus a <em>technology layer</em>: Serra lists eight add-ons (data access policies, metadata catalog, MDM, data virtualization, real-time processing, APIs, services, products) and calls it a fabric once ~3+ are present. Fabric is still <strong>centralized</strong> — it&#39;s the MDW with better plumbing.</li><li><strong>Data mesh</strong> — an <em>organizational</em> layer, not a product: domain ownership + data-as-product.</li></ul>',4)),(o(),l(d,null,{default:t(()=>[r(i,{id:"mermaid-231",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20MDW%5B%22Modern%20Data%20Warehouse%20%E2%80%94%20two%20tiers%22%5D%0A%20%20%20%20direction%20TB%0A%20%20%20%20L1%5B%22Data%20lake%3A%20land%2C%20transform%2C%20ML%22%5D%20--%3E%7C%22copy%20curated%20data%22%7C%20R1%5B%22RDW%20tier%3A%20BI%2C%20dashboards%3Cbr%2F%3Erow%2Fcol%20security%2C%20high%20concurrency%22%5D%0A%20%20end%0A%20%20subgraph%20LHS%5B%22Lakehouse%20%E2%80%94%20one%20tier%22%5D%0A%20%20%20%20direction%20TB%0A%20%20%20%20L2%5B%22Data%20lake%20%2B%20table%20format%3Cbr%2F%3EACID%2C%20DML%2C%20time%20travel%22%5D%20--%3E%20B2%5B%22BI%20engines%20%2B%20ML%20read%20same%20tables%22%5D%3B%0A%20%20end%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[a(" Loading... ",-1)])]),_:1})),e[16]||(e[16]=s('<p>The MDW pays a <strong>duplication tax</strong>: extra storage, extra pipelines, and a second copy of truth that can drift. The lakehouse removes the tax but gives up RDW-grade machinery — MPP joins, indexing, caching, materialized views, row/column security, high dashboard concurrency, and a <em>forced</em> metadata layer where schema-on-write guarantees the metadata always matches the data.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Fabric ≠ mesh — different axes entirely</p><p>Fabric is a <strong>technology</strong> decision; mesh is an <strong>org-chart</strong> decision. They compose, not compete: each mesh domain can run its own fabric internally. &quot;Should we do fabric or mesh?&quot; is a category error — the real question is &quot;does our bottleneck live in the plumbing (fabric) or the org (mesh)?&quot;</p></div><details class="details custom-block"><summary>Serra&#39;s lakehouse trade-off checklist — what you lose skipping the RDW</summary><ul><li>Millisecond dashboard queries (MPP joins, columnstore indexes, result caching, materialized views)</li><li>Row-level / column-level security, dynamic masking, workload management, high concurrency</li><li>A forced metadata layer — in file-land the catalog can drift or go missing entirely</li><li>ANSI-SQL tooling comfort — Spark-centric stacks can mean retraining users and rewriting procs/views</li></ul><p>His rule: none of these alone is a showstopper — PoC it. If BI users tolerate 5-second queries, skip the RDW; if they need millisecond dashboards, you&#39;ve just rediscovered the MDW.</p></details><h2 id="the-comparison-that-matters" tabindex="-1">The comparison that matters <a class="header-anchor" href="#the-comparison-that-matters" aria-label="Permalink to &quot;The comparison that matters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Warehouse</th><th>Data Lake</th><th>Lakehouse</th><th>Data Mesh</th></tr></thead><tbody><tr><td>Schema</td><td>On write, enforced</td><td>On read, optional</td><td>On write (enforced by format)</td><td>Per-domain, federated</td></tr><tr><td>Storage cost/TB</td><td>High ($$$)</td><td>Lowest</td><td>Lowest</td><td>Same as underlying stack</td></tr><tr><td>Query cost</td><td>Predictable, pricey</td><td>Cheap storage, expensive scans</td><td>Medium</td><td>Varies by domain</td></tr><tr><td>ACID / updates</td><td>Native</td><td>None (object store append only)</td><td>Yes via table format</td><td>Inherited</td></tr><tr><td>BI performance</td><td>Excellent</td><td>Poor without format layer</td><td>Good</td><td>Depends on products</td></tr><tr><td>ML/raw-data access</td><td>Awkward</td><td>Native</td><td>Native</td><td>Per domain</td></tr><tr><td>Governance</td><td>Centralized, strong</td><td>Weak → swamp</td><td>Strong if you build it</td><td>Federated, hardest</td></tr><tr><td>Vendor lock-in</td><td>Highest</td><td>Lowest</td><td>Medium (format open, engine swappable)</td><td>Architectural, not vendor</td></tr><tr><td>Org fit</td><td>Small/mid team</td><td>DE-heavy</td><td>DE-heavy + platform team</td><td>Large eng orgs only</td></tr></tbody></table><h2 id="how-to-actually-choose" tabindex="-1">How to actually choose <a class="header-anchor" href="#how-to-actually-choose" aria-label="Permalink to &quot;How to actually choose&quot;">​</a></h2>',6)),(o(),l(d,null,{default:t(()=>[r(i,{id:"mermaid-449",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22Workload%20mix%3F%22%5D%20--%3E%7C%22Mostly%20BI%20on%20curated%20data%2C%20small%20team%22%7C%20W%5B%22Warehouse%3Cbr%2F%3ESnowflake%20%2F%20BigQuery%22%5D%3B%0A%20%20S%20--%3E%7C%22ML-heavy%2C%20raw%20data%2C%20big%20team%22%7C%20L%5B%22Lakehouse%3Cbr%2F%3EIceberg%2FDelta%20on%20object%20store%22%5D%3B%0A%20%20S%20--%3E%7C%22Mixed%20BI%20%2B%20ML%20at%20scale%22%7C%20LH%5B%22Lakehouse%20%2B%20warehouse%20for%20serving%22%5D%3B%0A%20%20L%20--%3E%20O%7B%22Org%20%3E%20~50%20eng%20teams%3F%22%7D%3B%0A%20%20O%20--%3E%7Cyes%7C%20M%5B%22Add%20mesh%20operating%20model%22%5D%3B%0A%20%20O%20--%3E%7Cno%7C%20D%5B%22Done%20%E2%80%94%20centralized%20ownership%22%5D%3B%0A%20%20W%20--%3E%20D%3B%0A%20%20LH%20--%3E%20O%3B%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[a(" Loading... ",-1)])]),_:1})),e[17]||(e[17]=s('<div class="info custom-block"><p class="custom-block-title">ℹ️ Heuristic</p><p>Default 2026 answer for a new platform: <strong>lakehouse table format on object storage</strong> (Iceberg is the current gravitational center) with a managed query engine on top. Pure warehouse for BI-only teams; mesh only when org structure demands it.</p></div><h3 id="the-scored-decision-table-serra-s-framework" tabindex="-1">The scored decision table (Serra&#39;s framework) <a class="header-anchor" href="#the-scored-decision-table-serra-s-framework" aria-label="Permalink to &quot;The scored decision table (Serra&#39;s framework)&quot;">​</a></h3><p>Serra&#39;s core argument is that there is <strong>no one-size-fits-all architecture</strong> — you score your own org, not the vendor&#39;s slide deck. Weight each factor 1–5 for your situation:</p><table tabindex="0"><thead><tr><th>Factor</th><th>Score low →</th><th>Score high →</th><th>Where high points</th></tr></thead><tbody><tr><td>Org size</td><td>Few domains, one data team</td><td>Dozens of domains, federated teams</td><td>Mesh only at the top end</td></tr><tr><td>Data team maturity</td><td>Analysts + SQL only</td><td>Platform team, data engineers per domain</td><td>Lakehouse / mesh need high</td></tr><tr><td>Governance needs</td><td>Loose, internal use only</td><td>Regulated: lineage, row/col security, audit</td><td>MDW / warehouse tier</td></tr><tr><td>Tooling appetite</td><td>Prefer managed, pay for convenience</td><td>Run OSS formats, own compaction/catalog</td><td>Lakehouse</td></tr><tr><td>Data volume</td><td>under 10 TB, BI-centric</td><td>Big + streaming + semi-structured</td><td>MDW → fabric at scale</td></tr></tbody></table>',4)),(o(),l(d,null,{default:t(()=>[r(i,{id:"mermaid-551",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22Low%20maturity%3Cbr%2F%3Esmall%20org%2C%20SQL-only%20team%22%5D%20--%3E%20B%5B%22Warehouse%20or%20MDW%22%5D%3B%0A%20%20C%5B%22Medium%3Cbr%2F%3Eplatform%20team%20exists%22%5D%20--%3E%20D%5B%22Lakehouse%20%2B%20managed%20engine%22%5D%3B%0A%20%20E%5B%22High%3Cbr%2F%3Efabric%20add-ons%3A%20catalog%2C%20MDM%2C%3Cbr%2F%3Evirtualization%2C%20streaming%22%5D%20--%3E%20F%5B%22Data%20fabric%22%5D%3B%0A%20%20G%5B%22Very%20high%3Cbr%2F%3Edomain-owned%20engineering%20%2B%3Cbr%2F%3Eexecutive%20mandate%22%5D%20--%3E%20H%5B%22Data%20mesh%22%5D%3B%0A"})]),fallback:t(()=>[...e[6]||(e[6]=[a(" Loading... ",-1)])]),_:1})),e[18]||(e[18]=s('<div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Serra&#39;s readiness gate for mesh is brutal: Dehghani&#39;s own self-assessment lists ~9 criteria (domain-oriented org, exec sponsorship, modern engineering culture, bleeding-edge tolerance, data-as-asset literacy...) and <em>all</em> must be somewhat/highly applicable — in his experience maybe <strong>1% of companies qualify</strong>. The rarest scores are &quot;early adopter,&quot; &quot;domain-oriented org structure,&quot; and &quot;modern engineering practices.&quot; If you can&#39;t reorg the company by domains, you don&#39;t have a mesh — you have data federation, which is fine, but call it what it is.</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ Mesh myth-busting</p><p>Two myths Serra kills: (1) mesh <em>replaces</em> your lake/warehouse — no, it reorganizes who owns them; (2) data virtualization alone = mesh — no, federation satisfies only the domain-ownership principle, not data-as-product. And &quot;partial mesh&quot; (hub-and-spoke: mesh domains extending a still-centralized platform) is the realistic path, not the pure model.</p></div><h2 id="the-real-world-hybrid-medallion-on-a-lakehouse" tabindex="-1">The real-world hybrid: medallion on a lakehouse <a class="header-anchor" href="#the-real-world-hybrid-medallion-on-a-lakehouse" aria-label="Permalink to &quot;The real-world hybrid: medallion on a lakehouse&quot;">​</a></h2><p>Almost nobody runs a <em>pure</em> architecture anymore. The common production shape:</p>',4)),(o(),l(d,null,{default:t(()=>[r(i,{id:"mermaid-568",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20ING%5B%22Ingest%22%5D%0A%20%20%20%20S1%5B%22OLTP%20CDC%22%5D%20--%3E%20BR%5B%22Bronze%3Cbr%2F%3Eraw%2C%20append-only%22%5D%0A%20%20%20%20S2%5B%22Kafka%20events%22%5D%20--%3E%20BR%3B%0A%20%20%20%20S3%5B%22SaaS%20extracts%22%5D%20--%3E%20BR%3B%0A%20%20end%0A%20%20subgraph%20CUR%5B%22Curate%22%5D%0A%20%20%20%20BR%20--%3E%20SL%5B%22Silver%3Cbr%2F%3Ecleaned%2C%20conformed%2C%20deduped%22%5D%3B%0A%20%20%20%20SL%20--%3E%20GD%5B%22Gold%3Cbr%2F%3Estar%20schemas%20%2F%20marts%22%5D%3B%0A%20%20end%0A%20%20GD%20--%3E%20BI%5B%22BI%20%C2%B7%20serving%20%C2%B7%20reverse%20ETL%22%5D%3B%0A%20%20BR%20--%3E%20ML%5B%22ML%20%2F%20DS%20%E2%80%94%20reads%20raw%20directly%22%5D%3B%0A"})]),fallback:t(()=>[...e[7]||(e[7]=[a(" Loading... ",-1)])]),_:1})),e[19]||(e[19]=s('<p>Bronze/silver/gold is the <em>data-quality</em> layering the lakehouse gives you for free — warehouses can ingest semi-structured raw (Snowflake VARIANT, BigQuery JSON, external tables) but treat it as staging, while open-format lakehouses make raw a first-class, engine-portable layer. A raw lake can&#39;t enforce silver quality (no schema enforcement). The medallion pattern is the lakehouse&#39;s killer workflow.</p><h2 id="cost-model-intuition" tabindex="-1">Cost model intuition <a class="header-anchor" href="#cost-model-intuition" aria-label="Permalink to &quot;Cost model intuition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cost driver</th><th>Warehouse</th><th>Lakehouse</th></tr></thead><tbody><tr><td>Storage</td><td>Premium $$$/TB-month</td><td>Object-store $/TB-month</td></tr><tr><td>Query</td><td>Credits/slots — predictable, expensive</td><td>Engine-dependent — cheaper but ops burden</td></tr><tr><td>Ingest/ETL</td><td>Load credits + transform compute</td><td>Spark/Flink compute + format compaction jobs</td></tr><tr><td>Hidden cost</td><td>Egress + migration lock-in</td><td>Compaction, clustering, catalog ops you own</td></tr><tr><td>Break-even</td><td>BI-heavy, spiky query load</td><td>Write-heavy, ML-heavy, multi-engine</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Warehouses price for <em>convenience</em> — auto-optimization, zero tuning. Lakehouses are cheaper per byte but you pay in headcount: someone runs compaction, tunes partitions, maintains the catalog. Below ~5 engineers the warehouse&#39;s ops-free model usually wins on total cost even at higher $/TB.</p></div><p>Serra adds the two cost levers people forget: the MDW&#39;s <strong>duplication tax</strong> (paying for the same data in lake <em>and</em> RDW storage, plus the pipelines to keep them in sync — and risking silos when they drift) versus the lakehouse&#39;s <strong>serverless-per-query</strong> upside when you skip the RDW copy entirely. His governance corollary: an RDW forces schema-on-write, so metadata can never detach from the data — in a file-based lakehouse the catalog is optional plumbing, and &quot;the metadata drifted from the data&quot; is a governance failure you now own.</p><h2 id="migrating-between-architectures" tabindex="-1">Migrating between architectures <a class="header-anchor" href="#migrating-between-architectures" aria-label="Permalink to &quot;Migrating between architectures&quot;">​</a></h2><p>Migrations are the expensive part — so plan the <em>exit</em> before you pick the entry:</p><table tabindex="0"><thead><tr><th>From → To</th><th>Pattern</th><th>The catch</th></tr></thead><tbody><tr><td>OLTP → Warehouse</td><td>CDC + scheduled ELT into star schemas</td><td>Schema drift breaks ETL; late-arriving dimensions</td></tr><tr><td>Warehouse → Lakehouse</td><td>Unload to open format (Iceberg) in your own bucket</td><td>Stored procs/UDFs don&#39;t port; credit-burn query tuning needs redoing</td></tr><tr><td>Lake → Lakehouse</td><td>Register existing files under a table format</td><td>No data move needed — the format is metadata. The work is schema + partitioning</td></tr><tr><td>Any → Mesh</td><td>Replatform domains one at a time onto a self-serve stack</td><td>Org change disguised as a migration; needs executive ownership, not a project plan</td></tr></tbody></table><details class="details custom-block"><summary>Deep dive: the &quot;strangler fig&quot; pattern for storage</summary><p>Don&#39;t big-bang migrate. Stand up the new architecture, route <em>new</em> workloads to it, backfill historical data in parallel, and cut over consumers mart-by-mart — the same strangler-fig approach used for microservice migrations. The kill signal isn&#39;t &quot;all data moved&quot; — it&#39;s &quot;all consumers moved.&quot; Tables nobody reads get archived, not migrated.</p></details><h2 id="what-senior-engineers-actually-optimize-for" tabindex="-1">What senior engineers actually optimize for <a class="header-anchor" href="#what-senior-engineers-actually-optimize-for" aria-label="Permalink to &quot;What senior engineers actually optimize for&quot;">​</a></h2><p>The architecture decision is rarely &quot;which is best&quot; — it&#39;s &quot;which failure mode can we absorb.&quot;</p><ul><li><strong>Can&#39;t afford a platform team?</strong> Warehouse. Auto-everything is worth the premium.</li><li><strong>Can&#39;t afford lock-in?</strong> Open table format on your own bucket — engine-swappable forever.</li><li><strong>Can&#39;t afford a swamp?</strong> Enforce schema + catalog from day one — governance is cheaper at ingest than retrofit.</li><li><strong>Can&#39;t afford central bottleneck?</strong> Mesh — but only after the org can actually own quality.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ The two-platform tax is the default failure</p><p>Most real-world &quot;architectures&quot; are accidental: a lake stood up for ML, a warehouse bought for BI, and a nightly ETL job shuffling truth between them. The lakehouse&#39;s entire value proposition is killing that middle leg. If your diagram has an arrow labelled &quot;sync to warehouse,&quot; that&#39;s the thing to delete.</p></div><h2 id="failure-modes-to-quote-in-an-interview" tabindex="-1">Failure modes to quote in an interview <a class="header-anchor" href="#failure-modes-to-quote-in-an-interview" aria-label="Permalink to &quot;Failure modes to quote in an interview&quot;">​</a></h2><ul><li><strong>Swamp</strong>: ingest with no catalog, retention, or ownership.</li><li><strong>Two-platform tax</strong>: lake for ML + warehouse for BI, with nightly ETL between them — the classic 2015-2020 architecture the lakehouse exists to kill.</li><li><strong>Lock-in</strong>: proprietary format means migration = rewrite. Snowflake egress + re-ETL cost is real money at scale.</li><li><strong>Mesh theatre</strong>: &quot;self-serve platform&quot; that is actually a Jira queue to the data team.</li><li><strong>Format sprawl</strong>: Delta in one team, Iceberg in another, CSV-landing zones everywhere — a swamp wearing a nicer costume.</li></ul><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',16)),r(h,{questions:[{q:"A company stores all data as Parquet on S3 and queries via Trino. A BI team complains queries are slow and updates are impossible. What is the minimal architectural fix?",options:["Add more Trino workers","Move everything to Snowflake","Switch from Parquet to CSV for flexibility","Add an open table format like Iceberg on top of the files"],correct:3,explain:"The missing layer is table metadata — ACID, partition pruning, schema enforcement. Iceberg adds it without a migration: same files, same bucket, any engine."},{q:"What is the defining technical property of a lakehouse?",options:["It requires Hadoop","It uses Snowflake on the frontend","ACID transactions and schema enforcement on open file formats in object storage","It stores data in proprietary micro-partitions"],correct:2,explain:"The table format layer (Delta/Iceberg/Hudi) supplies ACID and schema management on top of open files — that combination is the lakehouse definition."},{q:"A data lake turns into a swamp primarily because of:",options:["Streaming ingestion","No catalog, ownership, lifecycle, or schema enforcement at ingest","Object storage costs growing","Too much Parquet compression"],correct:1,explain:"Lakes fail on governance debt, not technology. Files without metadata/ownership stop being discoverable and trustworthy."},{q:"Data mesh is best described as:",options:["A file format","An operating model: domain ownership + data-as-product + self-serve platform + federated governance","A CDC technology","A faster data warehouse"],correct:1,explain:"Mesh decentralizes ownership to domains. It is an organizational architecture — buying software cannot install it."},{q:"BigQuery and Snowflake both charge more per TB than S3 because:",options:["They store data on SSDs","They replicate data more","You are paying for the managed query layer, automatic optimization, and proprietary storage format that only their engine can read","Marketing"],correct:2,explain:"The premium buys the tightly integrated storage+compute+optimization — and the lock-in that comes with a format only that engine reads."},{q:"When does data mesh become the right choice?",options:["When you want cheaper storage","When a centralized data team is the bottleneck in a large, mature engineering org","Always, it is the modern default","When you have lots of data"],correct:1,explain:"Mesh solves an org-scale coordination problem. Below ~dozens of domain teams, centralization is simpler and faster."}]}),r(h,{questions:[{q:"Per Serra, what separates a Modern Data Warehouse from a lakehouse?",options:["The MDW replicates at least some data from the lake into a separate RDW tier; a lakehouse keeps everything in one tier","The lakehouse cannot store Parquet files","The MDW uses only Snowflake","Nothing, they are synonyms"],correct:0,explain:"Serra's litmus test: no RDW copy means it is a lakehouse. The MDW pays a duplication tax; the lakehouse deletes the serving tier entirely."},{q:"Data fabric vs data mesh — the correct framing is:",options:["They are competing products","Fabric is a technology layer on top of a centralized architecture; mesh is an organizational layer, and each mesh domain can run its own fabric","Fabric is only for unstructured data","Mesh is a vendor product you can buy"],correct:1,explain:"Different axes: fabric answers a plumbing problem (catalog, virtualization, MDM, real-time), mesh answers an org-scaling problem. They compose rather than compete."},{q:"Serra reports that roughly how many companies pass Dehghani's full data mesh readiness assessment?",options:["About 25%","About half","All of them, since mesh is just software","About 1% — all criteria must be somewhat or highly applicable, and early-adopter, domain-oriented structure, and modern engineering scores are rare"],correct:3,explain:"The bar is organizational: exec sponsorship, domain reorg, modern engineering culture. Fail the org test and what you built is data federation, not mesh."}]}),e[20]||(e[20]=s('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://www.databricks.com/glossary/data-lakehouse" target="_blank" rel="noreferrer">Data lakehouse overview — Databricks</a></li><li><a href="https://cloud.google.com/learn/what-is-a-data-warehouse" target="_blank" rel="noreferrer">What is a data warehouse? — Google Cloud</a></li><li><a href="https://aws.amazon.com/what-is/data-lake/" target="_blank" rel="noreferrer">What is a data lake? — AWS</a></li><li><a href="https://aws.amazon.com/what-is/data-warehouse/" target="_blank" rel="noreferrer">What is a data warehouse? — AWS</a></li><li><a href="https://martinfowler.com/articles/data-mesh-principles.html" target="_blank" rel="noreferrer">Data Mesh principles — martinfowler.com</a></li><li><a href="https://iceberg.apache.org/docs/latest/" target="_blank" rel="noreferrer">Apache Iceberg docs</a></li><li><a href="https://docs.delta.io/latest/index.html" target="_blank" rel="noreferrer">Delta Lake docs</a></li><li><strong>Deciphering Data Architectures</strong> — James Serra (2024), <a href="https://www.oreilly.com/library/view/deciphering-data-architectures/9781098150754/" target="_blank" rel="noreferrer">O&#39;Reilly</a></li></ul>',2))])}const B=m(g,[["render",p]]);export{v as __pageData,B as default};
